"""
Robust batch trend smoother with endpoint-aligned public output.

All filtering functions return indices window_size - 1 through len(x) - 1.
"""
import numpy as np


def _as_finite_1d(x):
    a = np.asarray(x, dtype=float).reshape(-1)
    if a.size == 0:
        return a
    if np.all(np.isfinite(a)):
        return a
    good = np.isfinite(a)
    if not np.any(good):
        return np.zeros_like(a)
    return np.interp(np.arange(a.size), np.flatnonzero(good), a[good])


def adaptive_filter(x, window_size=20):
    x = _as_finite_1d(x)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    return np.convolve(x, np.ones(window_size) / float(window_size), mode="valid")


def _hysteresis(y, factor):
    """Suppress only short opposite derivative excursions."""
    y = np.asarray(y, dtype=float).copy()
    if y.size < 3:
        return y
    d = np.diff(y)
    scale = 1.4826 * np.median(np.abs(d - np.median(d)))
    if not np.isfinite(scale) or scale <= 1e-12:
        return y
    threshold = factor * scale
    direction = 0
    pending = 0.0
    for i in range(1, len(y)):
        step = y[i] - y[i - 1]
        sd = 1 if step > 0 else (-1 if step < 0 else 0)
        if direction == 0:
            if sd:
                direction = sd
            continue
        if sd == 0 or sd == direction:
            pending = 0.0
        else:
            pending += step
            if abs(pending) >= threshold:
                direction = sd
                pending = 0.0
            else:
                y[i] = y[i - 1]
    return y


def _candidate_cost(candidate, observed, window_size):
    residual = candidate - observed
    d = np.diff(candidate)
    mad_r = np.median(np.abs(residual - np.median(residual)))
    mad_d = np.median(np.abs(d - np.median(d))) if d.size else 0.0
    if d.size > 1:
        signs = np.sign(d)
        reversals = np.mean(signs[1:] != signs[:-1])
    else:
        reversals = 0.0
    recent = np.mean(np.abs(residual[-min(window_size, residual.size):]))
    return float(0.48 * mad_r + 0.28 * mad_d + 0.16 * reversals + 0.08 * recent)


def enhanced_filter_with_trend_preservation(x, window_size=20):
    x = _as_finite_1d(x)
    n = len(x)
    if n < window_size:
        raise ValueError(
            f"Input signal length ({n}) must be >= window_size ({window_size})"
        )
    if n <= 3:
        return x[window_size - 1:].copy()

    d = np.diff(x)
    sigma = np.median(np.abs(d - np.median(d))) / (0.67448975 * np.sqrt(2.0))
    sigma = max(float(sigma), 1e-10)
    trend = None

    try:
        from scipy.interpolate import UnivariateSpline

        t = np.arange(n, dtype=float)
        order = min(3, n - 1)
        base = n * sigma * sigma
        fitted = []
        for mult in (0.45, 0.8, 1.35, 2.3):
            weights = np.ones(n, dtype=float)
            estimate = None
            for _ in range(2):
                fit = UnivariateSpline(t, x, w=weights, s=base * mult, k=order)
                estimate = np.asarray(fit(t), dtype=float)
                r = x - estimate
                rs = 1.4826 * np.median(np.abs(r - np.median(r)))
                cap = 1.345 * max(sigma, float(rs), 1e-10)
                weights = np.minimum(1.0, cap / (np.abs(r) + 1e-12))
            if estimate is not None and np.all(np.isfinite(estimate)):
                fitted.append(estimate)
        if fitted:
            trend = min(
                fitted,
                key=lambda z: _candidate_cost(z, x, window_size)
            )
    except Exception:
        trend = None

    if trend is None:
        try:
            from scipy.signal import butter, sosfiltfilt
            ratio = sigma / (np.std(x) + 1e-12)
            cutoff = float(np.clip(0.13 / (1.0 + ratio), 0.055, 0.13))
            sos = butter(3, cutoff, btype="lowpass", output="sos")
            trend = sosfiltfilt(sos, x, padlen=min(12, n - 1))
        except Exception:
            span = min(n if n % 2 else n - 1, max(3, 2 * (window_size // 2) + 1))
            pad = span // 2
            trend = np.convolve(
                np.pad(x, (pad, pad), mode="edge"),
                np.ones(span) / float(span),
                mode="valid",
            )

    trend = np.asarray(trend, dtype=float)
    choices = []
    for alpha in (0.0, 0.08, 0.16, 0.24):
        blended = trend + alpha * (x - trend)
        for deadband in (0.70, 0.90, 1.10):
            candidate = _hysteresis(blended, deadband)
            if np.all(np.isfinite(candidate)):
                choices.append((_candidate_cost(candidate, x, window_size), candidate))

    full = min(choices, key=lambda p: p[0])[1] if choices else trend
    if not np.all(np.isfinite(full)):
        full = x.copy()
    return np.asarray(full, dtype=float)[window_size - 1:]


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    np.random.seed(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(np.random.randn(length) * 0.05)
    noisy_signal = clean_signal + np.random.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(signal_length, noise_level)
    else:
        noisy_signal = _as_finite_1d(noisy_signal)
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")
    if clean_signal is None:
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered_signal),
        }

    delay = window_size - 1
    aligned_clean = clean_signal[delay:]
    aligned_noisy = noisy_signal[delay:]
    m = min(len(filtered_signal), len(aligned_clean))
    filtered_signal = filtered_signal[:m]
    aligned_clean = aligned_clean[:m]
    aligned_noisy = aligned_noisy[:m]

    correlation = (
        np.corrcoef(filtered_signal, aligned_clean)[0, 1]
        if m > 1 and np.std(filtered_signal) > 0 and np.std(aligned_clean) > 0
        else 0
    )
    before = np.var(aligned_noisy - aligned_clean)
    after = np.var(filtered_signal - aligned_clean)
    reduction = (before - after) / before if before > 0 else 0

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": aligned_clean,
        "noisy_signal": aligned_noisy,
        "correlation": correlation,
        "noise_reduction": reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")
